// ========================================
// Admin Commands Handler — n8n Code Node
// Webhook منفصل لأرقام الإدارة فقط
// ========================================
// /status                   → ملخص الـ leads
// /lead +966XXXXXXXXX       → تفاصيل عميل
// /assign +966X <اسم>       → تعيين موظف
// /pause +966X              → إيقاف follow-ups
// /resume +966X [stage]     → استئناف follow-ups
// ========================================

const SUPABASE_URL = 'https://xfibcjhshpmqkrhlpsoa.supabase.co';
const SUPABASE_KEY = 'eyJ-REDACTED-SERVICE-ROLE';

// ── Checkpoint 2: Admin allowlist ─────────────────────
const ADMIN_PHONES = ['966XXXXXXXXX', '966YYYYYYYYY']; // ← استبدل بأرقامك

const raw         = $input.first().json;
const msgData     = raw.data || raw;
const senderPhone = msgData?.key?.remoteJid?.replace('@s.whatsapp.net', '');
const msgText     = (
  msgData?.message?.conversation ||
  msgData?.message?.extendedTextMessage?.text || ''
).trim();

// ── Security Gate ─────────────────────────────────────
if (!senderPhone || !ADMIN_PHONES.includes(senderPhone)) {
  console.log(`[ADMIN] REJECTED — ${senderPhone}`);
  return [{ json: { reply: null, rejected: true } }];
}

if (!msgText.startsWith('/')) {
  return [{ json: { reply: null } }];
}

const parts = msgText.split(/\s+/);
const cmd   = parts[0].toLowerCase();
console.log(`[ADMIN] ${senderPhone} → ${cmd}`);

// ── Helpers ───────────────────────────────────────────
async function sb(method, path, body) {
  const r = await fetch(`${SUPABASE_URL}/rest/v1/${path}`, {
    method,
    headers: {
      'apikey': SUPABASE_KEY,
      'Authorization': `Bearer ${SUPABASE_KEY}`,
      'Content-Type': 'application/json',
      'Prefer': 'return=representation',
    },
    body: body ? JSON.stringify(body) : undefined,
  });
  return r.json();
}

function formatLead(l) {
  const fu = l.next_followup
    ? new Date(l.next_followup).toLocaleString('ar-SA', { timeZone: 'Asia/Riyadh' })
    : 'لا يوجد';
  return [
    `📋 *${l.name || 'بدون اسم'}*`,
    `📱 ${l.phone}`,
    `🏷️ المرحلة: *${l.stage}*`,
    `🌍 الوجهة: ${l.destination || '—'}`,
    `🔁 Follow-ups: ${l.follow_up_count}/2`,
    `⏰ القادم: ${fu}`,
    `⏸️ موقوف: ${l.paused ? 'نعم' : 'لا'}`,
    `👤 المسؤول: ${l.assigned_to || 'غير محدد'}`,
    `📝 ملاحظات: ${l.notes || '—'}`,
  ].join('\n');
}

const DELAYS = { quoted: 30, interested: 120, followup: 1440 };
let reply = '';

// ── /status ───────────────────────────────────────────
if (cmd === '/status') {
  const all = await sb('GET', 'leads?select=stage,paused,next_followup,follow_up_count');
  if (!Array.isArray(all)) { reply = '❌ خطأ في الاتصال بقاعدة البيانات'; }
  else {
    const counts = {};
    let pendingFU = 0;
    all.forEach(l => {
      counts[l.stage] = (counts[l.stage] || 0) + 1;
      if (!l.paused && l.next_followup && l.follow_up_count < 2) pendingFU++;
    });
    reply = [
      `📊 *ملخص الـ Leads*`,
      `──────────────────`,
      `📥 إجمالي: ${all.length}`,
      `💬 quoted: ${counts.quoted || 0}`,
      `💡 interested: ${counts.interested || 0}`,
      `🔄 followup: ${counts.followup || 0}`,
      `📋 manual_quote: ${counts.manual_quote || 0}`,
      `✅ closed: ${counts.closed || 0}`,
      `❌ lost: ${counts.lost || 0}`,
      `──────────────────`,
      `⏰ Follow-ups معلقة: ${pendingFU}`,
    ].join('\n');
  }
}

// ── /lead <phone> ─────────────────────────────────────
else if (cmd === '/lead' && parts[1]) {
  const phone = parts[1].replace('+', '');
  const data  = await sb('GET', `leads?phone=eq.${phone}&select=*`);
  reply = (!Array.isArray(data) || data.length === 0)
    ? `❌ لا يوجد عميل بهذا الرقم: ${phone}`
    : formatLead(data[0]);
}

// ── /assign <phone> <name> ────────────────────────────
else if (cmd === '/assign' && parts[1] && parts[2]) {
  const phone = parts[1].replace('+', '');
  const name  = parts.slice(2).join(' ');
  const data  = await sb('PATCH', `leads?phone=eq.${phone}`, { assigned_to: name });
  reply = (Array.isArray(data) && data.length > 0)
    ? `✅ تم تعيين *${name}* لـ ${phone}`
    : `❌ لم يُعثر على العميل: ${phone}`;
}

// ── /pause <phone> ────────────────────────────────────
else if (cmd === '/pause' && parts[1]) {
  const phone = parts[1].replace('+', '');
  const data  = await sb('PATCH', `leads?phone=eq.${phone}`, { paused: true });
  reply = (Array.isArray(data) && data.length > 0)
    ? `⏸️ تم إيقاف follow-ups لـ ${phone}`
    : `❌ لم يُعثر على العميل: ${phone}`;
}

// ── /resume <phone> [stage] ───────────────────────────
else if (cmd === '/resume' && parts[1]) {
  const phone      = parts[1].replace('+', '');
  const newStage   = parts[2] || null;
  const leads      = await sb('GET', `leads?phone=eq.${phone}&select=*`);

  if (!Array.isArray(leads) || leads.length === 0) {
    reply = `❌ لم يُعثر على العميل: ${phone}`;
  } else {
    const lead     = leads[0];
    const useStage = newStage || lead.stage;
    const delay    = DELAYS[useStage];
    const nextFU   = delay ? new Date(Date.now() + delay * 60 * 1000).toISOString() : null;
    const update   = { paused: false, next_followup: nextFU };
    if (newStage) update.stage = newStage;
    const res = await sb('PATCH', `leads?phone=eq.${phone}`, update);
    const fuStr = nextFU
      ? new Date(nextFU).toLocaleString('ar-SA', { timeZone: 'Asia/Riyadh' })
      : 'لا يوجد';
    reply = (Array.isArray(res) && res.length > 0)
      ? `▶️ تم استئناف follow-ups لـ ${phone}\n⏰ القادم: ${fuStr}`
      : `❌ خطأ في التحديث`;
  }
}

// ── Unknown ───────────────────────────────────────────
else {
  reply = [
    `❓ الأوامر المتاحة:`,
    `/status`,
    `/lead +966XXXXXXXXX`,
    `/assign +966X اسم الموظف`,
    `/pause +966X`,
    `/resume +966X [stage]`,
  ].join('\n');
}

return [{ json: { reply, to: senderPhone } }];
